  const script = `
const fs=require('fs');
const res=JSON.parse(fs.readFileSync('/tmp/res.json','utf8'));
for (const [f, picks] of Object.entries(res)) {
  let t=fs.readFileSync(f,'utf8'); let i=0;
  t=t.replace(/<<<<<<< HEAD\\n([\\s\\S]*?)=======\\n([\\s\\S]*?)>>>>>>> [^\\n]*\\n/g,(m,a,b)=>{const r=picks[i++]; if(r==='ours')return a; if(r==='theirs')return b; if(r==='both')return a+b; return r;});
  if(i!==picks.length) throw new Error(f+' count '+i);
  fs.writeFileSync(f,t);
}`;
  await edit("/tmp/res.js", { revision: null, changes: [{ kind: "replaceFile", content: script }] });
  await edit("/tmp/res.json", { revision: null, changes: [{ kind: "replaceFile", content: JSON.stringify(p) }] });
  return execFile("node", ["/tmp/res.js"]);
}

